	private static Dictionary<string, string> _byKey;
	private static Dictionary<string, string> _labels;
	private static string[] _codes;

	/// <summary>按显示顺序排列的所有章节编码。</summary>
	internal static string[] OrderedCodes
	{
		get
		{
			string[] c = _codes;
			if (c == null)
			{
				var list = new List<string>(ChapterGroupLines.Length);
				foreach (string line in ChapterGroupLines)
				{
					int i = line.IndexOf('|');
					if (i > 0) { list.Add(line.Substring(0, i)); }
				}
				c = list.ToArray();
				_codes = c;
			}
			return c;
		}
	}

	/// <summary>章节编码 → 显示名；查不到返回编码本身。</summary>
	internal static string LabelOf(string code)
	{
		if (string.IsNullOrEmpty(code)) { return ""; }
		Dictionary<string, string> m = _labels;
		if (m == null)
		{
			m = new Dictionary<string, string>(ChapterGroupLines.Length);
			foreach (string line in ChapterGroupLines)
			{
				string[] p = line.Split('|');
				if (p.Length >= 2 && p[0].Length > 0) { m[p[0]] = p[1]; }
			}
			_labels = m;
		}
		return m.TryGetValue(code, out string label) ? label : code;
	}

	/// <summary>查植物所属章节编码；查不到返回 ""。</summary>
	internal static string ChapterOf(string plantKey)
	{
		if (string.IsNullOrEmpty(plantKey)) { return ""; }
		Dictionary<string, string> map = _byKey;
		if (map == null)
		{
			map = new Dictionary<string, string>(PlantChapterLines.Length);
			foreach (string line in PlantChapterLines)
			{
				int i = line.IndexOf('|');
				if (i <= 0) { continue; }
				map[line.Substring(0, i)] = line.Substring(i + 1);
			}
			_byKey = map;
		}
		return map.TryGetValue(plantKey, out string g) ? g : "";
	}
